SELECT School, City, AdmFName1, AdmLName1, AdmFName2, AdmLName2, AdmFName3, AdmLName3
FROM schools
WHERE Charter = 1 AND CharterNum = '00D2';

SELECT AdmLName1, District, County, School
FROM schools
WHERE CharterNum = '40';

SELECT
    SUM(CASE WHEN status = 'A' THEN amount ELSE 0 END) * 100.0 / SUM(amount) AS percentage
FROM loan;

SELECT 
    CAST(SUM(CASE WHEN type = 'gold' AND strftime('%Y', issued) < '1998' THEN 1 ELSE 0 END) AS REAL) / COUNT(*) * 100 AS percent_gold
FROM card;

SELECT atom_id, (SELECT COUNT(DISTINCT bond_type) FROM bond WHERE molecule_id = 'TR346') AS bond_type_count
FROM atom
WHERE molecule_id = 'TR346';

SELECT 
    COUNT(CASE WHEN borderColor = 'borderless' THEN 1 END) * 100.0 / COUNT(*) AS percentage
FROM cards;

SELECT 
  100.0 * SUM(CASE WHEN isTextless = 1 AND layout = 'normal' THEN 1 ELSE 0 END) / COUNT(isTextless)
FROM cards;

SELECT SUM(publisher_id = 13) * 100.0 / COUNT(publisher_id) AS percentage
FROM superhero
WHERE height_cm BETWEEN 150 AND 180;

SELECT
    100.0 * SUM(CASE WHEN eye_colour_id = 7 THEN 1 ELSE 0 END) / COUNT(*) AS percentage
FROM superhero;

SELECT COUNT(DISTINCT driverId) AS driver_count
FROM results
WHERE raceId = 18;

SELECT COUNT(*)
FROM results
WHERE raceId > 50 AND raceId < 100 AND time IS NOT NULL AND statusId = 2;

SELECT m.department
FROM major m
WHERE m.major_id IN (
    SELECT link_to_major FROM member WHERE last_name = 'Pierce'
)
AND m.major_id IN (
    SELECT link_to_major FROM member WHERE last_name = 'Guidi'
);

SELECT DISTINCT department
FROM major
WHERE college = 'College of Humanities and Social Sciences';

SELECT AVG(Price * Amount) AS avg_total_price
FROM transactions_1k
WHERE Date LIKE '2012-01%';
